<section class="card"><h2>Vypsat nový termín</h2><form method="post" class="form-grid"><?php token() ?><input type="hidden" name="action" value="create_session"><?php foreach(['lesson_id'=>['Lekce','SELECT id,name FROM lessons WHERE active=1 ORDER BY name'],'trainer_id'=>['Trenér','SELECT id,name FROM trainers WHERE active=1 ORDER BY name'],'room_id'=>['Sál','SELECT id,CONCAT(name," (max. ",capacity,")") AS name FROM rooms ORDER BY id']] as $name=>$def): ?><label><?=e($def[0])?><select name="<?=$name?>" required><option value="">Vyberte…</option><?php foreach(all($def[1]) as $o): ?><option value="<?=$o['id']?>"><?=e($o['name'])?></option><?php endforeach ?></select></label><?php endforeach ?><?php field('starts_at','Začátek','datetime-local','',true); field('capacity','Kapacita','number',12,true,'min="1" max="500"'); ?><div class="form-end"><button>Zveřejnit termín</button></div></form></section>
<div class="section-title"><h2>Vypsané termíny</h2></div><div class="table-wrap card"><table><thead><tr><th>Lekce</th><th>Čas</th><th>Trenér / sál</th><th>Obsazeno</th><th>Stav</th><th>Akce</th></tr></thead><tbody><?php foreach(all(SESSION_SELECT.'ORDER BY s.starts_at DESC LIMIT 300') as $s): ?><tr><td><strong><?=e($s['lesson_name'])?></strong></td><td><?=e(stamp($s['starts_at']))?><small>do <?=e(date('H:i',strtotime($s['ends_at'])))?></small></td><td><?=e($s['trainer_name'])?><small><?=e($s['room_name'])?></small></td><td><?=$s['booked']?> / <?=$s['capacity']?></td><td><?=$s['status']==='cancelled'?'Zrušeno':(strtotime($s['starts_at'])<time()?'Proběhlý termín':'Zveřejněno')?></td><td><?php if($s['status']==='published' && strtotime($s['starts_at'])>time()): action_form('cancel_session',['session_id'=>$s['id']],'Zrušit termín','button small secondary','Zrušit celý termín včetně všech rezervací?'); else: ?>—<?php endif ?></td></tr><?php endforeach ?></tbody></table></div><p class="muted">Zobrazeno nejvýše 300 posledních termínů. Chybný budoucí termín zrušte a vypište znovu; historie rezervací zůstane zachována.</p>
