<?php elseif($page==='admin-reservations'): heading('PROVOZ','Rezervace a docházka','Docházku lze označit od 30 minut před začátkem. Správce může rezervaci zrušit i po uplynutí klientské lhůty.');
$filter=filter_var($_GET['session']??0,FILTER_VALIDATE_INT)?:0; ?>
<form class="filters card" method="get"><input type="hidden" name="page" value="admin-reservations"><label>Termín<select name="session"><option value="0">Všechny termíny</option><?php foreach(all('SELECT s.id,s.starts_at,l.name FROM sessions s JOIN lessons l ON l.id=s.lesson_id ORDER BY s.starts_at DESC') as $s): ?><option value="<?=$s['id']?>" <?=$filter===$s['id']?'selected':''?>><?=e(stamp($s['starts_at']).' · '.$s['name'])?></option><?php endforeach ?></select></label><button>Zobrazit</button></form>
<?php $sql='SELECT b.*,u.name,u.email,l.name AS lesson_name,s.starts_at,s.status AS session_status FROM reservations b JOIN users u ON u.id=b.user_id JOIN sessions s ON s.id=b.session_id JOIN lessons l ON l.id=s.lesson_id'; $rows=all($sql.($filter?' WHERE s.id=?':'').' ORDER BY s.starts_at DESC,u.name LIMIT 500',$filter?[$filter]:[]); if(!$rows): empty_state('Zatím zde nejsou žádné rezervace.'); else: ?>
<div class="table-wrap card"><table><thead><tr><th>Klient</th><th>Lekce</th><th>Stav</th><th>Docházka</th><th>Akce</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><strong><?=e($r['name'])?></strong><small><?=e($r['email'])?></small></td><td><?=e($r['lesson_name'])?><small><?=e(stamp($r['starts_at']))?></small></td><td><?=$r['status']==='active'?'Aktivní':'Zrušená'?></td><td><?php if($r['status']==='active' && $r['session_status']==='published' && strtotime($r['starts_at'])<=time()+1800): ?><form method="post" class="row-form"><?php token() ?><input type="hidden" name="action" value="attendance"><input type="hidden" name="reservation_id" value="<?=$r['id']?>"><label class="sr-only" for="attendance-<?=$r['id']?>">Docházka <?=e($r['name'])?></label><select id="attendance-<?=$r['id']?>" name="attendance"><?php foreach(['pending','present','absent'] as $a): ?><option value="<?=$a?>" <?=$r['attendance']===$a?'selected':''?>><?=e(attendance_label($a))?></option><?php endforeach ?></select><button class="small">Uložit</button></form><?php else: ?><?=$r['status']==='active'?e(attendance_label($r['attendance'])):'—'?><?php endif ?></td><td><?php if($r['status']==='active'): action_form('admin_cancel_booking',['reservation_id'=>$r['id']],'Zrušit','button small secondary','Opravdu zrušit tuto rezervaci?'); else: ?>—<?php endif ?></td></tr><?php endforeach ?></tbody></table></div><p class="muted">Zobrazeno nejvýše 500 rezervací. Pro konkrétní lekci použijte filtr termínu.</p><?php endif ?>
